// sum of their events, or whose completions differ from their completion
// rows. Events without a progress row show up with zero progress.
func (q *Queries) ReconcileStampProgress(ctx context.Context) ([]ReconcileStampProgressRow, error) {
	rows, err := q.db.Query(ctx, reconcileStampProgress)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ReconcileStampProgressRow
	for rows.Next() {
		var i ReconcileStampProgressRow
		if err := rows.Scan(
			&i.AppID,
			&i.MemberID,
			&i.StampCardID,
			&i.Count,
			&i.Completions,
			&i.EventSum,
			&i.CompletionRows,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const setStampProgress = `-- name: SetStampProgress :exec
UPDATE stamp_progress SET
  count           = $1,
  completions     = $2,
  last_stamped_at = coalesce($3, last_stamped_at),
  updated_at      = $4
WHERE app_id = $5 AND member_id = $6 AND stamp_card_id = $7
`

type SetStampProgressParams struct {
	Count         int32              `json:"count"`
	Completions   int32              `json:"completions"`
	LastStampedAt pgtype.Timestamptz `json:"last_stamped_at"`
	Now           pgtype.Timestamptz `json:"now"`
	AppID         uuid.UUID          `json:"app_id"`
	MemberID      uuid.UUID          `json:"member_id"`
	StampCardID   uuid.UUID          `json:"stamp_card_id"`
}

func (q *Queries) SetStampProgress(ctx context.Context, arg SetStampProgressParams) error {
	_, err := q.db.Exec(ctx, setStampProgress,
		arg.Count,
		arg.Completions,
		arg.LastStampedAt,
		arg.Now,
		arg.AppID,
		arg.MemberID,
		arg.StampCardID,
	)
	return err
}

const stampCardInUse = `-- name: StampCardInUse :one
SELECT EXISTS (SELECT 1 FROM stamp_events WHERE app_id = $1 AND stamp_card_id = $2)::boolean AS in_use
`

type StampCardInUseParams struct {
	AppID       uuid.UUID `json:"app_id"`
	StampCardID uuid.UUID `json:"stamp_card_id"`
}

// True once any member has a stamp event on the card.
func (q *Queries) StampCardInUse(ctx context.Context, arg StampCardInUseParams) (bool, error) {
	row := q.db.QueryRow(ctx, stampCardInUse, arg.AppID, arg.StampCardID)
	var in_use bool
	err := row.Scan(&in_use)
	return in_use, err
}

const sumVisitStamps = `-- name: SumVisitStamps :one
SELECT coalesce(sum(delta), 0)::integer AS stamps
FROM stamp_events
WHERE app_id = $1 AND stamp_card_id = $2
  AND member_id = $3 AND reason = 'stamp'
  AND created_at > $4
`

type SumVisitStampsParams struct {
	AppID       uuid.UUID          `json:"app_id"`
	StampCardID uuid.UUID          `json:"stamp_card_id"`
	MemberID    uuid.UUID          `json:"member_id"`
	Since       pgtype.Timestamptz `json:"since"`
}

// Stamps the member got on the card since a moment (now minus the visit
// window), whatever the scan, for max_stamps_per_visit. Call it after
// LockStampProgress so concurrent stamps see each other's rows.
func (q *Queries) SumVisitStamps(ctx context.Context, arg SumVisitStampsParams) (int32, error) {
	row := q.db.QueryRow(ctx, sumVisitStamps,
		arg.AppID,
		arg.StampCardID,
		arg.MemberID,
		arg.Since,
	)
	var stamps int32
	err := row.Scan(&stamps)
	return stamps, err
}

const updateStampCard = `-- name: UpdateStampCard :one
UPDATE stamp_cards SET
  name                      = coalesce($1, name),
  description               = CASE WHEN $2::boolean THEN $3 ELSE description END,
  stamps_required           = coalesce($4, stamps_required),
  reward_coupon_template_id = CASE WHEN $5::boolean
                                   THEN $6 ELSE reward_coupon_template_id END,
  max_stamps_per_visit      = coalesce($7, max_stamps_per_visit),
  status                    = coalesce($8, status),
  updated_at                = $9
WHERE app_id = $10 AND id = $11
RETURNING id, tenant_id, app_id, name, description, stamps_required, reward_coupon_template_id, max_stamps_per_visit, status, created_at, updated_at
`

type UpdateStampCardParams struct {
	Name                      *string            `json:"name"`
	SetDescription            bool               `json:"set_description"`
	Description               *string            `json:"description"`
	StampsRequired            *int32             `json:"stamps_required"`
	SetRewardCouponTemplateID bool               `json:"set_reward_coupon_template_id"`
	RewardCouponTemplateID    uuid.NullUUID      `json:"reward_coupon_template_id"`
	MaxStampsPerVisit         *int32             `json:"max_stamps_per_visit"`
	Status                    *string            `json:"status"`
	Now                       pgtype.Timestamptz `json:"now"`
	AppID                     uuid.UUID          `json:"app_id"`
	ID                        uuid.UUID          `json:"id"`
}

// Partial update: a NULL argument keeps the column; set_* flags let
// description and reward_coupon_template_id be cleared. stamps_required is
// fixed once StampCardInUse is true (the service checks). A reward template
// of another app fails the foreign key (SQLSTATE 23503). status 'active'
// reactivates an archived card.
func (q *Queries) UpdateStampCard(ctx context.Context, arg UpdateStampCardParams) (StampCard, error) {
	row := q.db.QueryRow(ctx, updateStampCard,
		arg.Name,
		arg.SetDescription,
		arg.Description,
		arg.StampsRequired,
		arg.SetRewardCouponTemplateID,
		arg.RewardCouponTemplateID,
		arg.MaxStampsPerVisit,
		arg.Status,
		arg.Now,
		arg.AppID,
		arg.ID,
	)
	var i StampCard
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.AppID,
		&i.Name,
		&i.Description,
		&i.StampsRequired,
		&i.RewardCouponTemplateID,
		&i.MaxStampsPerVisit,
		&i.Status,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
